/**
 * The「星落镇」sample models (fixtures/xingluo, generated by the fixtures line; read only here).
 * Skipped when the fixtures are not in this checkout.
 */
import fs from 'node:fs'
import path from 'node:path'
import { describe, expect, it, beforeAll } from 'vitest'
import { assetFileFor, createTestContext, fileRefFor } from '@bowerbird/plugin-sdk/testing'
import type { FormatHandler, Validator } from '@bowerbird/plugin-sdk'
import plugin from '../server.js'

const root = path.resolve(import.meta.dirname, '../../../../fixtures/xingluo')
const has = fs.existsSync(path.join(root, 'props/chest/chest.glb'))
const at = (p: string) => path.join(root, p)

let model: FormatHandler, validator: Validator

describe.skipIf(!has)('sample library models', () => {
  beforeAll(async () => {
    const ctx = createTestContext({ pluginId: 'bowerbird.model' })
    await plugin.activate(ctx)
    model = ctx.registered.formats.find(f => f.id === 'model')!
    validator = ctx.registered.validators[0]!
  })

  it('chest.glb: 2,480 faces, external texture slots, COLOR_0, the open clip, the design size', async () => {
    const p = at('props/chest/chest.glb')
    expect(await model.match(fileRefFor(p))).toMatchObject({ format: 'model' })
    const r = await model.probe!(assetFileFor(p))
    expect(r.badge).toBe('2,480 面')
    expect(r.tech).toMatchObject({ triangles: 2480, hasVertexColors: true, animations: 1, textures: 3 })
    expect(r.references).toEqual(expect.arrayContaining(['chest_basecolor.png', 'chest_normal.png', 'chest_orm.png']))
    expect(r.embedded ?? []).toEqual([])
    const s = await model.summarize!(assetFileFor(p))
    expect(s.text).toContain('open')
    const checks = await validator.check(assetFileFor(p, { designObject: { id: '0192f3a4-7c1e-7b52-9d06-4e8a51c0d201', targetSize: { w: 1.26, h: 0.95, d: 0.87 } } }))
    expect(checks[0]?.rule).toBe('size-vs-design')
    expect(checks[0]?.message).toMatch(/^尺寸与设计对象：模型 [\d.]+ × [\d.]+ × [\d.]+ m · 目标 1\.26 × 0\.95 × 0\.87 m/)
  })

  it('hero_walk.fbx (ASCII FBX 7.4): 8,912 faces, the walk stack, no metal-roughness', async () => {
    const p = at('characters/hero/hero_walk.fbx')
    expect(await model.match(fileRefFor(p))).toMatchObject({ format: 'model' })
    const r = await model.probe!(assetFileFor(p))
    expect(r.badge).toBe('8,912 面')
    expect(r.tech).toMatchObject({ triangles: 8912, animations: 1 })
    expect(r.tech.boundsX).toBeUndefined()
    const s = await model.summarize!(assetFileFor(p))
    expect(s.text).toContain('walk')
  })

  it('hero.glb and potion.glb read without errors; potion names its two textures', async () => {
    const hero = await model.probe!(assetFileFor(at('characters/hero/hero.glb')))
    expect(hero.tech).toMatchObject({ hasVertexColors: true, animations: 2 })
    const potion = await model.probe!(assetFileFor(at('props/potion/potion.glb')))
    expect(potion.references).toEqual(expect.arrayContaining(['potion_basecolor.png', 'potion_normal.png']))
  })

  it('does not claim the OBJ (ADR-022)', async () => {
    const p = at('environments/rock_01.obj')
    const declared = ['.glb', '.gltf', '.fbx']
    expect(declared.includes(path.extname(p))).toBe(false)
    expect(await model.match(fileRefFor(p))).toBeNull()
  })
})
